mapper.update:
UPDATE meeting_sync_outbox SET delivered_version = #{version}, claim_token = NULL, lease_until = NULL,
  attempt_count = 0, next_attempt_at = #{nextAttemptAt}, last_error_code = NULL, last_request_id = NULL,
  status = IF(desired_version <= #{version}, 'delivered', 'pending'), updated_at = #{now}
WHERE binding_id = #{bindingId} AND business_key = #{businessKey} AND claim_token = #{token}

UPDATE meeting_sync_outbox SET claim_token = NULL, lease_until = NULL, next_attempt_at = #{nextAttemptAt},
  last_error_code = #{errorCode}, last_request_id = #{requestId}, status = #{status}, updated_at = #{now}
WHERE binding_id = #{bindingId} AND business_key = #{businessKey} AND claim_token = #{token}

UPDATE meeting_sync_outbox SET claim_token = NULL, lease_until = NULL, status = 'blocked',
  last_error_code = #{errorCode}, last_request_id = #{requestId}, updated_at = #{now}
WHERE binding_id = #{bindingId} AND business_key = #{businessKey} AND claim_token = #{token}

UPDATE meeting_sync_outbox SET status = 'pending', attempt_count = 0, next_attempt_at = #{now},
  last_error_code = NULL, last_request_id = NULL, updated_at = #{now}
WHERE binding_id = #{bindingId} AND business_key = #{businessKey} AND status IN ('failed','blocked')
